import type {
  CreateEnvironmentOperation,
  CreateEnvironmentRefusal,
  OperationStartResult
} from "./create-environment-types.js";
import { setupStartConflictResponse } from "./operation-start-conflict.js";
import {
  findNamespaceClaimConflict,
  loadNamespaceClaims,
  type NamespaceClaimsPorts
} from "./create-environment-namespace-claims.js";

// Seam 1 of the `POST /api/create-environment` slice: the refusal ladder.
//
// Seven rungs, in this exact order, every one of them reached before the route
// performs any GitHub mutation:
//
//   1. 403 not server-owned            (before the body is even read)
//   2. 400 no target repository
//   3. 400 malformed repository slug
//   4. 409 continuation does not match the operation it claims to continue
//   5. 409 another setup is already running for the repo
//   6. 500 the setup recovery record could not be persisted
//   7. 409 the namespace is held by another environment, or its claims
//          could not be established
//
// Rung 6 also finalizes the operation as failed, because a record that cannot be
// saved must not be left looking live. Rungs are returned as data rather than
// written to the socket so the ladder is assertable without a live response.
//
// The namespace rung runs last of the pre-mutation checks, once the operation
// this request belongs to is settled. That ordering is required rather than
// cosmetic: the claim read is authoritative, so it must run as the GitHub
// account pinned to this operation, and that account is only known once the
// operation is adopted or started. It still precedes every GitHub mutation.

export const SERVER_OWNED_REFUSAL: CreateEnvironmentRefusal = {
  status: 403,
  body: {
    error: "This endpoint is reserved for server-owned operations.",
    code: "server-owned-operation-required"
  }
};

export interface CreateEnvironmentRequestData {
  repo?: string;
  environment?: string;
  operationEnvironment?: string;
  provider?: string;
  operationId?: unknown;
  origin?: string | null;
  resumeTarget?: string | null;
  resumeBranch?: string | null;
  branch?: string | null;
  resumeReason?: string | null;
  profileName?: string;
  clientId?: string;
  tenantId?: string;
  subscriptionId?: string;
  resourceGroup?: string;
  cluster?: string;
  location?: string;
  namespace?: string;
  roleArn?: string;
  region?: string;
  accountId?: string;
  vpcId?: string;
  subnetIds?: string;
}

export interface AdmissionPorts {
  isValidRepoSlug(repo: string): boolean;
  getOperation(operationId: string): CreateEnvironmentOperation | null;
  isStale(operation: CreateEnvironmentOperation): boolean;
  isTerminalState(state: unknown): boolean;
  createOperation(input: {
    provider: string;
    repo: string;
    environment: string;
    stages: unknown;
    journey: Record<string, unknown>;
  }): CreateEnvironmentOperation;
  buildStages(input: { includeIdentity: boolean }): unknown;
  startOperation(operation: CreateEnvironmentOperation): OperationStartResult;
  persistOperations(): Promise<void>;
  reportOperationDiagnostic(diagnostic: {
    code: string;
    message: string;
  }): void;
  finishFailed(
    operation: CreateEnvironmentOperation,
    failure: Record<string, unknown>
  ): void;
  enterStage(operation: CreateEnvironmentOperation, stage: string): void;
  errorMessage(error: unknown): string;
  stageAuthorizeIdentity: string;
  stageConfigureEnvironment: string;
  namespaceClaimsFor(operationId: string): NamespaceClaimsPorts | null;
}

export interface AdmittedCreateEnvironmentRequest {
  outcome: "admitted";
  operation: CreateEnvironmentOperation;
  targetRepo: string;
  envName: string;
  provider: string;
}

export interface RefusedCreateEnvironmentRequest {
  outcome: "refused";
  refusal: CreateEnvironmentRefusal;
  // The operation the caller must expose to its generic catch. Rungs 4 and 5
  // deliberately leave this null so a failed admission cannot finalize a record
  // the route does not own.
  operation: CreateEnvironmentOperation | null;
}

export type CreateEnvironmentAdmission =
  AdmittedCreateEnvironmentRequest | RefusedCreateEnvironmentRequest;

// Rung 1. Split out because it is decided before the request body is read.
export function refuseUnlessServerOwned(
  isServerOwned: boolean
): CreateEnvironmentRefusal | null {
  return isServerOwned ? null : SERVER_OWNED_REFUSAL;
}

// The namespace rung, factored out because it runs once the operation whose
// pinned GitHub account will perform the read is known: adopted on the
// continuation path, freshly started otherwise. It reads through that account
// rather than the ambient one, so a customer who passed readiness with the
// selected account is never refused because some other account cannot see the
// repository.
async function refuseClaimedNamespace(
  data: CreateEnvironmentRequestData,
  targetRepo: string,
  envName: string,
  provider: string,
  operationId: string,
  ports: AdmissionPorts
): Promise<CreateEnvironmentRefusal | null> {
  const unavailable = (reason: string): CreateEnvironmentRefusal => ({
    status: 409,
    body: {
      error: `Radius created nothing because it could not confirm which namespaces ${targetRepo}'s environments already use: ${reason}`,
      code: "namespace-claims-unavailable"
    }
  });
  const claimsPorts = ports.namespaceClaimsFor(operationId);
  if (!claimsPorts) {
    return unavailable(
      "the GitHub account pinned to this setup is unavailable."
    );
  }
  const claims = await loadNamespaceClaims(targetRepo, claimsPorts);
  if (!claims.ok) return unavailable(claims.reason);
  const conflict = findNamespaceClaimConflict(claims.claims, {
    provider,
    subscriptionId: data.subscriptionId ?? "",
    accountId: data.accountId ?? "",
    region: data.region ?? "",
    cluster: data.cluster ?? "",
    namespace: data.namespace ?? "",
    // Saving an environment must not collide with the namespace it already
    // holds. The form locks the name on edit, so the submitted name is the
    // environment being written.
    excludeEnvironment: envName
  });
  if (!conflict) return null;
  return {
    status: 409,
    body: {
      error: `Namespace "${conflict.namespace}" on cluster "${conflict.cluster}" already belongs to environment "${conflict.environment}". Radius allows one environment per namespace, so choose a different namespace or deploy to "${conflict.environment}".`,
      code: "namespace-already-claimed",
      environment: conflict.environment
    }
  };
}

// Rungs 2 through 7. Returns the adopted or freshly started operation on
// success, with the configure-environment stage already entered.
export async function admitCreateEnvironmentRequest(
  data: CreateEnvironmentRequestData,
  ports: AdmissionPorts
): Promise<CreateEnvironmentAdmission> {
  // `||` not `??`: an empty-string repo must fall through to the no-repo rung,
  // and an empty-string environment/provider must take the default.
  const targetRepo = data.repo || "";
  const envName = data.environment || "dev";
  const provider = data.provider || "azure";

  if (!targetRepo) {
    return {
      outcome: "refused",
      operation: null,
      refusal: {
        status: 400,
        body: { error: "No target repository specified." }
      }
    };
  }

  if (!ports.isValidRepoSlug(targetRepo)) {
    return {
      outcome: "refused",
      operation: null,
      refusal: {
        status: 400,
        body: {
          error: `Invalid repository "${targetRepo}". Expected "owner/repo".`,
          code: "invalid-repo"
        }
      }
    };
  }

  // Adopt the record /api/azure-auto-setup left running, so the two POSTs read
  // as one operation. When credentials already exist that route never ran, so
  // start a record here instead — with the identity stage omitted rather than
  // shown as skipped, because a stage that cannot happen has no business in the
  // checklist.
  const continuationId =
    typeof data.operationId === "string" ? data.operationId : "";
  if (continuationId) {
    const operationEnvironment =
      typeof data.operationEnvironment === "string" ?
        data.operationEnvironment
      : envName;
    const existing = ports.getOperation(continuationId);
    if (
      !existing ||
      ports.isStale(existing) ||
      // A record settled by stale reconciliation, a stop, or a failure is
      // closed, not resumable: continuing it would write new provenance into a
      // terminal record the customer has already been given a verdict for.
      ports.isTerminalState(existing.state) ||
      existing.repo !== targetRepo ||
      existing.environment !== operationEnvironment ||
      existing.provider !== provider ||
      (existing.currentStage !== ports.stageAuthorizeIdentity &&
        existing.currentStage !== ports.stageConfigureEnvironment) ||
      existing.inputRequired
    ) {
      return {
        outcome: "refused",
        operation: null,
        refusal: {
          status: 409,
          body: {
            error:
              "The environment request does not match the setup operation it is continuing.",
            code: "operation-continuation-mismatch",
            operationId: continuationId
          }
        }
      };
    }
    // Rung 7, on the continuation path: the operation is proven to match this
    // request, so its pinned account is the one to read the claims with.
    const adoptedRefusal = await refuseClaimedNamespace(
      data,
      targetRepo,
      envName,
      provider,
      existing.operationId,
      ports
    );
    if (adoptedRefusal) {
      return { outcome: "refused", operation: null, refusal: adoptedRefusal };
    }
    ports.enterStage(existing, ports.stageConfigureEnvironment);
    return {
      outcome: "admitted",
      operation: existing,
      targetRepo,
      envName,
      provider
    };
  }

  const operation = ports.createOperation({
    provider,
    repo: targetRepo,
    environment: envName,
    stages: ports.buildStages({ includeIdentity: false }),
    journey: {
      origin: data.origin || null,
      resumeTarget: data.resumeTarget || null,
      resumeBranch: data.resumeBranch || data.branch || null,
      resumeReason: data.resumeReason || null
    }
  });
  const started = ports.startOperation(operation);
  if (!started.ok) {
    return {
      outcome: "refused",
      operation: null,
      refusal: {
        status: 409,
        body: setupStartConflictResponse(targetRepo, started)
      }
    };
  }
  try {
    await ports.persistOperations();
  } catch (error) {
    ports.reportOperationDiagnostic({
      code: "operation-store-write-failed",
      message: `Could not persist setup operation ${operation.operationId}: ${ports.errorMessage(error)}`
    });
    ports.finishFailed(operation, {
      code: "operation-persistence-failed",
      stage: operation.currentStage,
      stepSeq: null,
      message:
        "Radius changed no cloud resources because it could not save the setup recovery record.",
      classification: "unknown"
    });
    return {
      outcome: "refused",
      operation,
      refusal: {
        status: 500,
        body: {
          error:
            "Radius changed no cloud resources because it could not save the setup recovery record.",
          code: "operation-persistence-failed",
          operationId: operation.operationId
        }
      }
    };
  }
  // Rung 7, on the fresh-start path: the record now exists, so the account
  // pinned to it is the one to read the claims with.
  const startedRefusal = await refuseClaimedNamespace(
    data,
    targetRepo,
    envName,
    provider,
    operation.operationId,
    ports
  );
  if (startedRefusal) {
    return { outcome: "refused", operation, refusal: startedRefusal };
  }
  ports.enterStage(operation, ports.stageConfigureEnvironment);
  return {
    outcome: "admitted",
    operation,
    targetRepo,
    envName,
    provider
  };
}
